select public.set_submission_visibility((select id from photos where n=1),'public');
select throws_ok($$select public.block_submission_user((select id from photos where n=1))$$,'42501','safety_unavailable','Self block rejected');
select throws_ok($$select public.report_public_content((select id from photos where n=1),'user','other')$$,'42501','safety_unavailable','Self report rejected');
