select throws_ok($$select public.report_public_content((select id from photos where n=1),'submission','other',repeat('x',501))$$,'22023','invalid_report','Details bounded');
select throws_ok($$select public.report_public_content((select id from photos where n=1),'unknown','other')$$,'22023','invalid_report','Target kind controlled');
